import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import numpy as np
import pandas as pd

RC_PARAMS = {
    "font.size": 9,
    "axes.labelsize": 9,
    "axes.titlesize": 9,
    "xtick.labelsize": 8,
    "ytick.labelsize": 8,
    "legend.fontsize": 8,
    "axes.linewidth": 0.8,
    "xtick.major.width": 0.8,
    "ytick.major.width": 0.8,
}

FIGSIZE = (3.4, 2.6)
PALETTE = ["#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#8C564B", "#000000"]
RECEDED_ALPHA = 0.4

DATA_PATH = "data/benchmarks.csv"
X_FIELD = "dataset"
Y_FIELD = "accuracy"
GROUP = "model"
SERIES_ORDER = ["baseline", "+augment", "+distill", "ours"]
EMPHASIS = "ours"
STEM = "04-accuracy-by-dataset"
FORMATS = ["png", "svg", "pdf"]
DPI = 600


def load():
    return pd.read_csv(DATA_PATH)


def series_names(frame):
    if SERIES_ORDER is not None:
        return list(SERIES_ORDER)
    return sorted(frame[GROUP].dropna().unique().tolist(), key=str)


def series_style(name, index):
    colour = PALETTE[index % len(PALETTE)]
    if EMPHASIS is None:
        return {"colour": colour, "width": 1.4, "alpha": 1.0, "zorder": 2}
    if name == EMPHASIS:
        return {"colour": colour, "width": 2.2, "alpha": 1.0, "zorder": 3}
    return {"colour": colour, "width": 1, "alpha": RECEDED_ALPHA, "zorder": 1}


def aggregate(df):
    keys = [X_FIELD, GROUP]
    return df.groupby(keys, as_index=False)[Y_FIELD].mean()


def draw(ax, df):
    frame = aggregate(df)
    categories = list(dict.fromkeys(frame[X_FIELD].tolist()))
    positions = np.arange(len(categories))
    names = series_names(frame)
    width = 0.8 / max(len(names), 1)
    for index, name in enumerate(names):
        subset = frame[frame[GROUP] == name].set_index(X_FIELD).reindex(categories)
        offset = (index - (len(names) - 1) / 2) * width
        style = series_style(name, index)
        ax.bar(
            positions + offset,
            subset[Y_FIELD].to_numpy(),
            width,
            label=str(name),
            color=style["colour"],
            alpha=style["alpha"],
            zorder=style["zorder"],
        )
    ax.set_xticks(positions)
    ax.set_xticklabels([str(value) for value in categories])


def finish(fig, ax):
    ax.set_xlabel("Dataset")
    ax.set_ylabel("Top-1 accuracy (%)")
    ax.set_ylim(bottom=0)
    ax.set_title("Accuracy across benchmarks")
    ax.grid(False)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    ax.legend(
        title=None,
        frameon=False,
        loc="upper center", bbox_to_anchor=(0.5, -0.18),
    )
    # tight_layout is skipped: it fights a legend anchored outside the axes.


def main():
    df = load()
    with plt.rc_context(RC_PARAMS):
        fig, ax = plt.subplots(figsize=FIGSIZE)
        draw(ax, df)
        finish(fig, ax)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            kwargs = {"bbox_inches": "tight"}
            if fmt == "png":
                kwargs["dpi"] = DPI
            fig.savefig(path, **kwargs)
            print(f"wrote {path}")
    plt.close(fig)


if __name__ == "__main__":
    main()
